// Scoped cross-dialect section framing and exact emitted text observations.
// preludes: form-stdlib/source-compiler-health.fk
section [form.bml] {
 class BmlSectionDialectReview {
  def bsdr-check(name,ok) {
   if ok then print(list("section-dialect",name,1)) else form_error(str_concat("section-dialect refusal: ",name));
   1;
  }
  def bsdr-high(dialect) {
   let text = str_concat("section ",str_concat("[",str_concat(dialect,"] { def probe(x) = if x then do let y = 40; add(y,2); end else 7; probe(1); }\n")));
   let expected = "(defn probe (x) (if x (do (let y 40) (add y 2)) 7))\n(probe 1)\n";
   bsdr-check(dialect,str_eq(form-source-compile-text(text,""),expected));
  }
  def bsdr-run() {
   let body = "\n ; punctuation } ( \" in a whole-line rule comment\n do ::= \"}\" => review-emit;\n end ::= do => review-emit;\n";
   let prefix = "(do 1 42) ; raw Form comment ) }\n";
   let suffix = "(do 3 43) ; another raw comment ( {\n";
   let section = str_concat("section ",str_concat("[review.bmf] {",str_concat(body,"}\n")));
   let out = form-source-compile-text(str_concat(prefix,str_concat(section,suffix)),"");
   let expected = str_concat(prefix,str_concat(fsc-compile-section("review.bmf",body,""),suffix));
   bsdr-check("custom-rule-text-and-raw-prefix-suffix",str_eq(out,expected));
   bsdr-check("do-rule-name",ge(str_find(out,"(list \"do\" (list \"sequence\" (review-op \"}\")) review-emit",0),0));
   bsdr-check("end-rule-name-and-do-reference",ge(str_find(out,"(list \"end\" (list \"sequence\" (review-ref \"do\")) review-emit",0),0));
   let tail = str_concat(body,"} ignored suffix");
   bsdr-check("actual-closing-brace-byte",eq(fsc-section-end(tail,0),str_len(body)));
   let neutral = "do ( arbitrary ) end { nested } }";
   bsdr-check("neutral-rule-delimiters",eq(fsc-section-end(neutral,0),sub(str_len(neutral),1)));
   bsdr-high("form.bml"); bsdr-high("form.action"); bsdr-high("form.route");
   bsdr-check("scoped-health-emission",sch-emission-observed?());
   1;
  }
 }
 bsdr-run();
}
